import{_ as n,C as s,o as t,c as r,a2 as a,b as i,w as o,a as c,E as l,a3 as h}from"./chunks/framework.Bqn-bhhR.js";const y=JSON.parse('{"title":"Semantic Search & Embeddings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/embeddings.md","filePath":"guide/embeddings.md","lastUpdated":1786047222000}'),m={name:"guide/embeddings.md"};function g(b,e,u,p,f,k){const d=s("Mermaid");return t(),r("div",null,[e[1]||(e[1]=a('<h1 id="semantic-search-embeddings" tabindex="-1">Semantic Search &amp; Embeddings <a class="header-anchor" href="#semantic-search-embeddings" aria-label="Permalink to &quot;Semantic Search &amp; Embeddings&quot;">​</a></h1><p>Codemark has two search modes: <strong>semantic</strong> (find by meaning) and <strong>full-text</strong> (find by substring). They are mutually exclusive — you pick one per query. This page covers how both work in <code>crates/codemark-core/src/embeddings/</code> and <code>storage/</code>.</p><h2 id="how-the-dispatch-chooses" tabindex="-1">How the dispatch chooses <a class="header-anchor" href="#how-the-dispatch-chooses" aria-label="Permalink to &quot;How the dispatch chooses&quot;">​</a></h2>',3)),(t(),i(h,null,{default:o(()=>[l(d,{id:"mermaid-9",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22codemark%20search%22%5D%20--%3E%20B%7B%22--collections%3F%22%7D%0A%20%20B%20--%20yes%20--%3E%20C%5B%22collection%20search%22%5D%0A%20%20B%20--%20no%20--%3E%20D%7B%22--semantic%3F%22%7D%0A%20%20D%20--%20yes%20--%3E%20E%5B%22semantic%20search%5CnVecStore%20KNN%20(vec0%20MATCH)%22%5D%0A%20%20D%20--%20no%20--%3E%20F%5B%22full-text%20search%5CnSQL%20LIKE%20'%25q%25'%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>There is no hybrid/rank-fusion. The <code>--semantic</code> flag selects the path once.</p><h2 id="full-text-search" tabindex="-1">Full-text search <a class="header-anchor" href="#full-text-search" aria-label="Permalink to &quot;Full-text search&quot;">​</a></h2><p>The default (non-semantic) path is <strong>SQL <code>LIKE</code> substring matching</strong>, not a full-text index. <code>search_bookmarks</code> builds dynamic SQL with <code>LIKE &#39;%query%&#39;</code> OR-joined across:</p><ul><li><code>bookmark_annotations.notes</code></li><li><code>bookmark_annotations.context</code></li><li><code>bookmark_tags.tag</code></li><li><code>bookmarks.file_path</code></li></ul><p>Results are ordered by <code>created_at DESC</code>. This keeps exact lookups fast and predictable.</p><details class="details custom-block"><summary>What about the FTS5 table?</summary><p>The schema contains a <code>bookmarks_fts</code> FTS5 table (created in early migrations), but it is <strong>not consulted</strong> by the search command — the production path scans the normalized tables directly with <code>LIKE</code>. It&#39;s effectively legacy.</p></details><h2 id="semantic-search" tabindex="-1">Semantic search <a class="header-anchor" href="#semantic-search" aria-label="Permalink to &quot;Semantic search&quot;">​</a></h2><p>Semantic search finds bookmarks by intent (&quot;where is authentication handled?&quot;) using <strong>local vector embeddings</strong> — no API key, no network call for inference.</p><h3 id="on-device-embedding-generation" tabindex="-1">On-device embedding generation <a class="header-anchor" href="#on-device-embedding-generation" aria-label="Permalink to &quot;On-device embedding generation&quot;">​</a></h3><p>Embeddings are generated 100% locally with <a href="https://github.com/huggingface/candle" target="_blank" rel="noreferrer">candle</a> on <strong>CPU only</strong>. The pipeline is a BERT sentence embedder:</p><ol><li><strong>Tokenize</strong> the input text.</li><li><strong>BERT forward pass</strong> → hidden states.</li><li><strong>Mean pooling</strong> over the (attention-mask-weighted) sequence axis.</li><li><strong>L2 normalize</strong> → a unit-length 384-dimensional vector.</li></ol><p>The model is lazily loaded once and cached in memory; model weights are fetched on first use from Hugging Face Hub and cached on disk.</p><h3 id="models" tabindex="-1">Models <a class="header-anchor" href="#models" aria-label="Permalink to &quot;Models&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Model</th><th>ID</th><th>Dimensions</th></tr></thead><tbody><tr><td><code>all-minilm-l6-v2</code> (default)</td><td><code>sentence-transformers/all-MiniLM-L6-v2</code></td><td>384</td></tr><tr><td><code>bge-small-en-v1.5</code></td><td><code>BAAI/bge-small-en-v1.5</code></td><td>384</td></tr></tbody></table><p>Both are 384-dimensional. The <code>vec0</code> virtual tables are created at <code>float[384]</code>.</p><h3 id="vector-storage" tabindex="-1">Vector storage <a class="header-anchor" href="#vector-storage" aria-label="Permalink to &quot;Vector storage&quot;">​</a></h3><p>Vectors live in <strong>sqlite-vec</strong> <code>vec0</code> virtual tables (<code>bookmark_embeddings</code>, <code>collection_embeddings</code>), loaded globally via <code>sqlite3_auto_extension</code> when the database opens. Embeddings are stored as little-endian f32 byte blobs. Re-indexing upserts atomically (delete + insert in a single transaction).</p><h3 id="distance-metrics" tabindex="-1">Distance metrics <a class="header-anchor" href="#distance-metrics" aria-label="Permalink to &quot;Distance metrics&quot;">​</a></h3><p>sqlite-vec returns Euclidean L2 distance. Because embeddings are L2-normalized, conversions to other metrics are exact and ranking-preserving:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Conversion from L2</th><th>Default threshold</th><th>Lower is better?</th></tr></thead><tbody><tr><td><code>l2</code> (default)</td><td>identity</td><td>1.3</td><td>yes</td></tr><tr><td><code>cosine</code></td><td>L2²/2 (= 1 − cos similarity)</td><td>0.85</td><td>yes</td></tr><tr><td><code>ip</code> (inner product)</td><td>1 − L2²/2 (= cos similarity)</td><td>0.15</td><td>no (higher is better)</td></tr></tbody></table><p>When a threshold is set, the search fetches more candidates first, converts each distance, filters by the threshold, then truncates to the limit.</p><h2 id="what-gets-embedded" tabindex="-1">What gets embedded <a class="header-anchor" href="#what-gets-embedded" aria-label="Permalink to &quot;What gets embedded&quot;">​</a></h2><p>The embedding text is enriched so semantic search matches structural intent, not just free-text notes:</p><ul><li><strong>Bookmarks</strong>: tags + first annotation&#39;s notes/context, then enriched with a tree-sitter query summary (<code>&quot;Node Type: function&quot;</code>, <code>&quot;Node Target: validate_token&quot;</code>).</li><li><strong>Collections</strong>: name + description + tags.</li></ul><h2 id="reindexing" tabindex="-1">Reindexing <a class="header-anchor" href="#reindexing" aria-label="Permalink to &quot;Reindexing&quot;">​</a></h2><p><code>codemark reindex</code> rebuilds embeddings for all bookmarks (and optionally collections). It&#39;s a <strong>full re-embed</strong>, not incremental — each row is delete-then-inserted. Scope it with <code>--lang</code> or <code>--collection</code>.</p><p>When you create a bookmark or collection, an embedding is generated <strong>best-effort, fire-and-forget</strong> — failures are swallowed so they never block the creating operation.</p>',27))])}const x=n(m,[["render",g]]);export{y as __pageData,x as default};
